//! Embeds the repository `catalog/` directory (spec 009, R7).
//!
//! Decision D-010 says adding a mapset is a pull request that touches only its
//! TOML file. A build script that scans `catalog/` keeps that promise: adding or
//! removing a recipe needs no Rust edit, and the recipes are compiled into the
//! binary so a release tarball can never lose them (the alternative — shipping a
//! `catalog/` directory next to the binary — adds a deployment step and a
//! runtime "catalog missing" failure mode for no benefit).
//!
//! The generated file defines `EMBEDDED_HOSTS`, `EMBEDDED_TAGS` (the spec 015
//! tag vocabulary), `EMBEDDED_RECIPES` and `EMBEDDED_SERIAL` (the catalog
//! serial, spec 019 R1/R3), consumed by `catalog::Catalog::embedded` and
//! `catalog::bundle`.

use std::env;
use std::fs;
use std::path::PathBuf;

fn main() {
    let manifest_dir = PathBuf::from(env::var("CARGO_MANIFEST_DIR").expect("CARGO_MANIFEST_DIR"));
    let catalog = manifest_dir.join("../../catalog");
    let out = PathBuf::from(env::var("OUT_DIR").expect("OUT_DIR"));
    let dest = out.join("embedded_catalog.rs");

    println!("cargo:rerun-if-changed={}", catalog.display());

    // Spec 019, R1/R3: the embedded catalog's serial is the UTC Unix time of
    // the source commit the catalog was built from. CI sets
    // `DDL_CATALOG_SERIAL` (`git log -1 --format=%ct`) for the catalog-bundle
    // job, so the published bundle and the release built from the same commit
    // agree; `SOURCE_DATE_EPOCH` is honoured as the reproducible-build
    // convention. Without either (a local or developer build) the serial is
    // `0`, meaning "unknown": every real published serial is then newer, which
    // is the safe direction — a development binary accepts the first bundle it
    // can reach instead of pinning itself to a serial it never learned.
    println!("cargo:rerun-if-env-changed=DDL_CATALOG_SERIAL");
    println!("cargo:rerun-if-env-changed=SOURCE_DATE_EPOCH");
    let serial = ["DDL_CATALOG_SERIAL", "SOURCE_DATE_EPOCH"]
        .iter()
        .find_map(|key| env::var(key).ok())
        .and_then(|value| value.trim().parse::<u64>().ok())
        .unwrap_or(0);

    let hosts = catalog.join("hosts.toml");
    if hosts.is_file() {
        println!("cargo:rerun-if-changed={}", hosts.display());
    }

    let tags = catalog.join("tags.toml");
    if tags.is_file() {
        println!("cargo:rerun-if-changed={}", tags.display());
    }

    let mut recipes: Vec<(String, PathBuf)> = Vec::new();
    match fs::read_dir(&catalog) {
        Ok(entries) => {
            for entry in entries.flatten() {
                let path = entry.path();
                if path.extension().and_then(|ext| ext.to_str()) != Some("toml") {
                    continue;
                }
                if matches!(
                    path.file_name().and_then(|name| name.to_str()),
                    Some("hosts.toml" | "tags.toml")
                ) {
                    continue;
                }
                let Some(name) = path.file_name().and_then(|name| name.to_str()) else {
                    continue;
                };
                println!("cargo:rerun-if-changed={}", path.display());
                recipes.push((name.to_owned(), path));
            }
        }
        Err(error) => {
            println!(
                "cargo:warning=catalog directory {} is unreadable ({error}); embedding no recipes",
                catalog.display()
            );
        }
    }
    recipes.sort();

    let mut code = String::new();
    code.push_str("// Generated by crates/ddl-core/build.rs — do not edit.\n");
    if hosts.is_file() {
        code.push_str(&format!(
            "pub static EMBEDDED_HOSTS: &str = include_str!({:?});\n",
            hosts.to_string_lossy().as_ref()
        ));
    } else {
        code.push_str("pub static EMBEDDED_HOSTS: &str = \"\";\n");
    }
    if tags.is_file() {
        code.push_str(&format!(
            "pub static EMBEDDED_TAGS: &str = include_str!({:?});\n",
            tags.to_string_lossy().as_ref()
        ));
    } else {
        code.push_str("pub static EMBEDDED_TAGS: &str = \"\";\n");
    }
    code.push_str("pub static EMBEDDED_RECIPES: &[(&str, &str)] = &[\n");
    for (name, path) in &recipes {
        code.push_str(&format!(
            "    ({name:?}, include_str!({:?})),\n",
            path.to_string_lossy().as_ref()
        ));
    }
    code.push_str("];\n");
    code.push_str(&format!(
        "/// Spec 019 R1/R3: UTC Unix time of the source commit, or 0 when unknown.\n\
         pub const EMBEDDED_SERIAL: u64 = {serial};\n"
    ));

    fs::write(&dest, code).expect("write embedded catalog module");
}
